function OrangePhotosTrashActions({ count, onClose, onRestore, onDelete, onEmpty }) {
  return <div className="od-orangephotos-selection-actions" role="toolbar" aria-label="Acciones de papelera">{count ? <><button className="od-orangephotos-header-icon" type="button" aria-label="Cerrar selección" title="Cerrar selección" onClick={onClose}>×</button><strong>{count} seleccionadas</strong><button className="od-orangephotos-header-icon" type="button" aria-label="Restaurar" title="Restaurar" onClick={onRestore}><IonIcon icon={arrowUndoOutline} /></button><button className="od-orangephotos-header-icon od-orangephotos-header-icon--danger" type="button" aria-label="Eliminar definitivamente" title="Eliminar definitivamente" onClick={onDelete}><IonIcon icon={trashOutline} /></button></> : <button className="od-orangephotos-empty-trash" type="button" aria-label="Vaciar papelera" title="Vaciar papelera" onClick={onEmpty}><IonIcon icon={trashOutline} /><span>Vaciar papelera</span></button>}</div>;
}

function getAlbumShareTitle(album) {
  const names = (album?.shared_people || []).map(person => person.display_name).filter(Boolean);
  if (!album?.is_shared_effectively) return "Privado";
  if (!album.is_owner) return `Compartido por ${album.shared_by_display_name || "otro miembro"}`;
  return album.visibility === "family" ? "Compartido con toda la familia" : `Compartido con ${names.join(", ") || "miembros concretos"}`;
}

function OrangeAlbumHeader({ album, onBack }) {
  if (!album) return null;
  const shareTitle = getAlbumShareTitle(album);
  return <header className="od-orange-album-detail-header"><button className="od-orange-album-detail-header__back" type="button" aria-label="Volver a álbumes" title="Volver a álbumes" onClick={onBack}><IonIcon icon={arrowBackOutline}/></button><div className="od-orange-album-detail-header__identity"><h1 className="od-page-title">{album.title}</h1><div className="od-orange-album-detail-header__meta"><span className={`od-orange-album-detail-header__share od-orange-photo-card__share--${album.is_owner ? "owned" : "received"}`} title={shareTitle} aria-label={shareTitle}><IonIcon icon={peopleOutline}/></span><span>{shareTitle}</span><span aria-hidden="true">·</span><span>{album.photo_count} elementos</span></div></div></header>;
}

function OrangeAlbumHeaderActions({
  album,
  canAdd,
  onShare,
  onAdd,
  onMore,
}) {
  return (
    <div
      className="od-orange-album-header-actions"
      role="toolbar"
      aria-label={`Acciones del álbum ${album.title}`}
    >
      {album.is_owner ? (
        <button type="button" className="od-orangephotos-header-icon" aria-label="Compartir álbum" title="Compartir álbum" onClick={onShare}>
          <IonIcon icon={shareSocialOutline} />
        </button>
      ) : null}
      {canAdd ? (
        <button type="button" className="od-orangephotos-header-icon" aria-label="Añadir fotos y vídeos" title="Añadir fotos y vídeos" onClick={onAdd}>
          <IonIcon icon={addOutline} />
        </button>
      ) : null}
      <button type="button" className="od-orangephotos-header-icon" aria-label="Actividad del álbum" title="Actividad del álbum: próximamente" disabled>
        <IonIcon icon={timeOutline} />
      </button>
      <button type="button" className="od-orangephotos-header-icon" aria-label="Más opciones del álbum" title="Más opciones" onClick={onMore}>
        <IonIcon icon={ellipsisVerticalOutline} />
      </button>
    </div>
  );
}

function OrangeAlbumContextMenu({ album, onAction }) {
  return <div className="od-orange-album-header-actions__menu">{album.is_owner?<><button className="od-action-menu-item" type="button" onClick={()=>onAction("rename")}>Cambiar nombre</button><button className="od-action-menu-item" type="button" onClick={()=>onAction("cover")}>Elegir imagen de portada</button></>:null}<button className="od-action-menu-item" type="button" onClick={()=>onAction("options")}>Opciones</button>{album.is_owner?<button className="od-action-menu-item od-action-menu-item--danger" type="button" onClick={()=>onAction("delete")}>Eliminar álbum</button>:null}</div>;
}

